class Solution {
public:
    string countAndSay(int n) {
        string s = "1";
        for (int i = 1; i < n; i++) {
            string next;
            int len = s.size();
            int j = 0;
            while (j < len) {
                int count = 1;
                while (j + count < len && s[j + count] == s[j]) {
                    count++;
                }
                next += to_string(count);
                next += s[j];
                j += count;
            }
            s = next;
        }
        return s;
    }
};
